"""reports/results.json and docs/REPORT.md, generated from a run. Do not edit them by hand."""

from __future__ import annotations

import json
from datetime import UTC, datetime
from pathlib import Path

from ..shared.config import ROOT, load, run_dir
from .gate import check
from .heldout import first_run_path, status


def _load(p: Path):
    return json.loads(p.read_text()) if p.exists() else None


def collect(profile: str) -> dict:
    d = run_dir(profile)
    study = _load(d / "study.json")
    set_name = load("profiles").get("heldout_set", "v1")
    first = _load(first_run_path(set_name)) if profile == "full" else None
    rerun = _load(d / "heldout.json")
    heldout = {**first, "blind": True, "status": status(set_name)} if first else ({**rerun, "blind": False} if rerun else None)
    serving = _load(d / "serving.json")
    metrics: dict[str, float | bool | None] = {}
    if study:
        prep = study["prepare"]
        metrics["prepare.feature_mismatches"] = prep["parity"]["mismatches"]
        metrics["prepare.dbt_failed"] = prep["dbt"]["failed"]
        f = study["frontier"]
        r = f["rules"]
        for name in f:
            if name == "rules":
                continue
            x = f[name]
            metrics[f"frontier.{name}.project_lift"] = x["project"] / r["project"] - 1
            metrics[f"frontier.{name}.revenue_ratio"] = x["revenue"] / r["revenue"]
            metrics[f"frontier.{name}.partner_profit_per_lead_lift"] = (
                x["partner_profit_per_lead"] / r["partner_profit_per_lead"] - 1
            )
            metrics[f"frontier.{name}.matched_lift"] = x["matched"] - r["matched"]
        for dsg, v in study["experiments"].items():
            for mt, s in v.items():
                metrics[f"experiments.{dsg}.{mt}.coverage"] = s["coverage"]
                metrics[f"experiments.{dsg}.{mt}.abs_relative_bias"] = (
                    abs(s["relative_bias"]) if s["relative_bias"] is not None else None
                )
        for mt, v in study["aa_budget_split_false_positive_rate"].items():
            metrics[f"experiments.aa_false_positive_rate.{mt}"] = v
    if heldout:
        for k, v in heldout["summary"].items():
            metrics[f"heldout.{k}"] = v
    if serving:
        metrics["serving.oversold_leads"] = serving["contention"]["oversold_leads"]
        metrics["serving.p95_ms"] = serving["latency"]["p95_ms"]
    slim = None
    if study:
        slim = {k: v for k, v in study.items() if k != "replications"}
        slim["truth_by_replication"] = [r["truth"] for r in study["replications"]]
        slim["global_by_replication"] = [r["global"] for r in study["replications"]]
    return {
        "generated_at": datetime.now(UTC).isoformat(),
        "profile": profile,
        "study": slim,
        "heldout": heldout,
        "serving": serving,
        "metrics": metrics,
    }


def f2(v, d=3):
    return "n/a" if v is None else (f"{v:.{d}f}" if isinstance(v, float) else str(v))


def pct(v, d=1):
    return "n/a" if v is None else f"{100 * v:+.{d}f}%"


def markdown(r: dict) -> str:
    out = [f"# Report\n\nGenerated by `mma report` ({r['generated_at']}, profile `{r['profile']}`). Do not edit.\n"]
    s = r["study"]
    if s:
        w = s["world"]
        prep = s["prepare"]
        out.append(
            f"## Data foundation\n\n{w['requests_per_month']:,} requests a month across {w['regions']} postcode regions and {w['categories']} categories, "
            f"{w['partners']:,} partners. Four months of logs under the current rules; dbt built {prep['dbt']['nodes']} nodes with {prep['dbt']['tests']} tests "
            f"({prep['dbt']['failed']} failed). Training rows: {prep['training_rows']:,}. Training/serving feature parity: "
            f"{prep['parity']['mismatches']} mismatches over {prep['parity']['pairs']:,} leads x 16 features.\n"
        )
        lines = [
            "| Model | Rows (train / calib / test) | AUC | Brier | ECE calibrated | ECE raw | Base rate |",
            "|---|---|---:|---:|---:|---:|---:|",
        ]
        for k in ("contact", "win"):
            m = prep["models"][k]
            t = m["test"]
            rows = m["rows"]
            lines.append(
                f"| {k} | {rows['train']:,} / {rows['calib']:,} / {rows['test']:,} | {t['auc']:.3f} | {t['brier']:.4f} | {t['ece']:.4f} | {m['test_uncalibrated']['ece']:.4f} | {t['base_rate']:.3f} |"
            )
        out.append("## Models\n\nTime-ordered slices; a label is used only once it has matured.\n\n" + "\n".join(lines) + "\n")
        f = s["frontier"]
        r0 = f["rules"]
        lines = [
            "| Policy | Matched | Projects | Revenue / request | Partner profit / lead | Leads | Called |",
            "|---|---:|---:|---:|---:|---:|---:|",
        ]
        for name, x in f.items():
            tag = (
                ""
                if name == "rules"
                else f" ({pct(x['project'] / r0['project'] - 1)} projects, {pct(x['revenue'] / r0['revenue'] - 1)} revenue)"
            )
            lines.append(
                f"| {name}{tag} | {x['matched']:.3f} | {x['project']:.4f} | {x['revenue']:.1f} | {x['partner_profit_per_lead']:.1f} | {x['leads']:,} | {x['contacted']:.3f} |"
            )
        out.append("## Matching: the evaluation month, every policy on the same requests\n\n" + "\n".join(lines) + "\n")
        lines = [
            "| Design | Metric | Mean estimate | True effect | Bias | Coverage of 95% CI | Mean SE |",
            "|---|---|---:|---:|---:|---:|---:|",
        ]
        for dsg, v in s["experiments"].items():
            for mt, x in v.items():
                lines.append(
                    f"| {dsg} | {mt} | {x['mean_estimate']:.4f} | {x['mean_truth']:.4f} | {x['bias']:.4f} | {x['coverage']:.2f} | {x['mean_se']:.4f} |"
                )
        aa = s["aa_budget_split_false_positive_rate"]
        out.append(
            f"## Experiments in a two-sided marketplace\n\n{len(s['truth_by_replication'])} replications of the evaluation month. The true effect is the model policy "
            "everywhere against the rules everywhere, on the same requests.\n\n"
            + "\n".join(f"- **{k}**: {v}" for k, v in s["designs"].items())
            + "\n\n"
            + "\n".join(lines)
            + f"\n\nA/A on the budget split (rules in both arms): false-positive rate {', '.join(f'{k} {v:.2f}' for k, v in aa.items())}.\n"
        )
    h = r["heldout"]
    if h:
        lines = [
            "| Scenario | What it stresses | Rules: projects | Model: projects | Revenue ratio | Partner profit / lead | Budget split covers truth |",
            "|---|---|---:|---:|---:|---:|---|",
        ]
        for x in h["results"]:
            bs = x["designs"]["budget_split"]["project"]
            cov = bs["lo"] <= x["truth"]["project"] <= bs["hi"]
            lines.append(
                f"| {x['name']} | {x['about']} | {x['rules']['project']:.4f} | {x['model']['project']:.4f} | {x['model']['revenue'] / x['rules']['revenue']:.3f} | "
                f"{x['rules']['partner_profit_per_lead']:.0f} -> {x['model']['partner_profit_per_lead']:.0f} | {'yes' if cov else 'no'} |"
            )
        sm = h["summary"]
        out.append(
            f"## Held-out worlds, set {h['set']}{': first run (blind)' if h['blind'] else ' (rerun)'}\n\nWritten from `heldout/WRITING_SCENARIOS.md` by someone who never saw the code. "
            f"{'Recorded ' + h.get('recorded_at', '') + ', kept as recorded. ' if h['blind'] else ''}Status: {h['status']}.\n\n"
            + "\n".join(lines)
            + f"\n\nThe model won more projects than the rules in {sm['project_lift_share']:.0%} of the worlds (mean lift {sm['mean_project_lift']:+.4f}); "
            f"revenue ratio min {sm['min_revenue_ratio']:.3f}, mean {sm['mean_revenue_ratio']:.3f}. The budget split's interval covered the true effect in "
            f"{sm['budget_split_project_covered']:.0%} of the worlds, the request split's in {sm['request_split_project_covered']:.0%}.\n"
        )
    sv = r["serving"]
    if sv:
        c, lat = sv["contention"], sv["latency"]
        out.append(
            f"## Serving\n\nTwo service instances on one Postgres, {c['threads']} threads, {c['requests']:,} requests, every partner's volume squeezed to {c['cap_squeezed_to']}: "
            f"{c['leads']:,} leads delivered, {c['reservations_refused_by_database']} reservations refused by the database, **{c['oversold_leads']} oversold**, "
            f"{c['decisions_vs_counter_mismatches']} mismatches between decisions and counters; a retried request returned the same decision: {c['retry_returns_same_decision']}. "
            f"Latency with the model, one thread: p50 {lat['p50_ms']:.1f} ms, p95 {lat['p95_ms']:.1f} ms.\n"
        )
    g = r.get("gate")
    if g:
        fmt = lambda v: f2(v) if isinstance(v, float) else str(v)  # noqa: E731
        out.append(
            "## Release gate\n\n| | Check | Actual | Required |\n|---|---|---:|---:|\n"
            + "\n".join(
                f"| {'pass' if x['ok'] else '**fail**'} | {x['name']} | {fmt(x['actual'])} | {x['op']} {x['value']} |"
                for x in g["floors"]
            )
            + "\n\nTargets (reported, not gated):\n\n| | Target | Actual | Aim |\n|---|---|---:|---:|\n"
            + "\n".join(
                f"| {'met' if x['ok'] else 'missed'} | {x['name']} | {fmt(x['actual'])} | {x['op']} {x['value']} |"
                for x in g["targets"]
            )
            + "\n"
        )
    return "\n".join(out)


def write_reports(profile: str) -> dict:
    r = collect(profile)
    rel = load("release")
    r["gate"] = {
        "floors": check(r["metrics"], rel["floors"], missing_ok=profile != "full"),
        "targets": check(r["metrics"], rel["targets"], missing_ok=True),
    }
    out = ROOT / "reports" if profile == "full" else run_dir(profile)
    out.mkdir(parents=True, exist_ok=True)
    (out / "results.json").write_text(json.dumps(r, indent=1, default=float))
    (ROOT / "docs" / "REPORT.md" if profile == "full" else out / "REPORT.md").write_text(markdown(r))
    return r
